steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending'}
try{
 $p='C:\TTiTTulares\ttittulares-mobile-trigger-state.json'
 $s=Get-Content $p -Raw | ConvertFrom-Json
 $id=[string]$s.editorial_retry_command_id
 $live=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'" | Where-Object { [string]$_.CommandLine -match 'Ejecutar[.]js|TT-Editorial-Guard[.]js' })
 if($live.Count){$o.state='deferred_active';$o.count=$live.Count}
 elseif($id -ne 'tt-autoguard-1794478562'){$o.state='different_retry_command';$o.command=$id}
 else{
  Copy-Item $p ($p+'.before-newchat-retry-20261112.bak') -Force
  $s.editorial_retry_after=[DateTimeOffset]::UtcNow.AddSeconds(-10).ToString('o')
  $tmp=$p+'.retry-tmp'
  [IO.File]::WriteAllText($tmp,($s|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
  Move-Item $tmp $p -Force
  Start-ScheduledTask -TaskName 'TTiTTulares Local'
  $o.state='same_command_retry_started';$o.command=$id
 }
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
